Lemma rg8_I : forall (last : bool) regs m (ps pd pe : Z) (bs0 bs1 bd : list byte) (v0 v1 vd : word),
  (0 <= ps)%Z -> (ps + 8 < 2 ^ 63)%Z -> (0 <= pd)%Z -> (pd + 4 <= pe)%Z -> (pe < 2 ^ 63)%Z -> (if last then pd + 4 = pe else pd + 4 < pe)%Z ->
  rdn SEGS m (Z_to_bv 64 ps) 4 = Some bs0 -> bytes_le_to_Z bs0 = bv_unsigned v0 ->
  rdn SEGS m (Z_to_bv 64 (ps + 4)) 4 = Some bs1 -> bytes_le_to_Z bs1 = bv_unsigned v1 ->
  rdn SEGS m (Z_to_bv 64 pd) 4 = Some bd -> bytes_le_to_Z bd = bv_unsigned vd ->
  store_ok SEGS m (Z_to_bv 64 pd) 4 = true ->
  getr regs 22 = Z_to_bv 64 (ps + 4) -> getr regs 23 = Z_to_bv 64 pd -> getr regs 7 = Z_to_bv 64 pe ->
  exists regs' (w : word),
    msteps SEGS (mkst regs (0x7c5ec : word) m rom)
                (mkst regs' (if last then (0x7c5c0 : word) else (0x7c5ec : word)) (wbytes m (Z_to_bv 64 pd) (word_to_le_bytes 4 w)) rom)
    /\ getr regs' 22 = Z_to_bv 64 (ps + 4 + 4) /\ getr regs' 23 = Z_to_bv 64 (pd + 4)
    /\ regs_agree (fun r => In r [22; 23; 24; 25; 31]%list) regs regs'.
