  (fw = true -> getr regs 1 = Z_to_bv 64 psf /\ getr regs 25 = Z_to_bv 64 (if f6 then 1 else 0) /\ getr regs 24 = Z_to_bv 64 (if f7 then 1 else 0)) ->
  getr regs 12 = Z_to_bv 64 dh ->
  exists regs',
    msteps SEGS (mkst regs (0x7b6f4 : word) m rom) (mkst regs' (if fw then (0x7b740 : word) else (0x7b7dc : word)) m rom)
    /\ (fw = true -> getr regs' 1 = Z_to_bv 64 (psf + 4) /\ getr regs' 18 = Z_to_bv 64 (4 * swpl) /\ getr regs' 20 = Z_to_bv 64 (4 * dwpl)
                     /\ getr regs' 21 = Z_to_bv 64 (if f6 then 1 else 0) /\ getr regs' 22 = Z_to_bv 64 (if f7 then 1 else 0) /\ getr regs' 23 = Z_to_bv 64 dh)
    /\ regs_agree (fun r => In r [1; 10; 11; 18; 20; 21; 22; 23]%list) regs regs'.
Proof.
